/* The bounds the loader applies to a kerning glyph's data block and kerning
   table, in the kerning configuration, which is the only one that compiles
   them. Each malformed font is paired with the same font made well formed, so
   that a refusal is the bound's and not the font's.

   Builds on gx_validation_binres_glyph_range.h: a one-page font with one glyph
   record, patched after it is built.  */

#include <stdio.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_validation_utility.h"
#include "gx_system.h"

TEST_PARAM test_parameter = {0};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

static TX_THREAD               Guix_API_Test;
static VOID      control_thread_entry(ULONG);
static ULONG     control_thread_stack[1024];

VOID tx_application_define(void *first_unused_memory)
{
    gx_validation_application_define(first_unused_memory);

    /* Termiante the test if it runs for more than 100 ticks */
    /* This function is not implemented yet. */
    gx_validation_watchdog_create(100);

    tx_thread_create(&Guix_API_Test, "GUIX API Test", control_thread_entry,
                     0, control_thread_stack, sizeof(control_thread_stack),
                     GX_SYSTEM_THREAD_PRIORITY + 1, GX_SYSTEM_THREAD_PRIORITY + 1,
                     TX_NO_TIME_SLICE, TX_AUTO_START);
}

/* Replace the default graphics driver with the validation driver. */
#ifdef win32_graphics_driver_setup_24xrgb
#undef win32_graphics_driver_setup_24xrgb
#endif
#define win32_graphics_driver_setup_24xrgb  gx_validation_graphics_driver_setup_24xrgb

#ifdef WIN32
#undef WIN32
#endif

#include "gx_validation_wrapper.h"
#include "demo_kerning_glyph_draw_32bpp_screen.c"
#include "gx_validation_binres_glyph_range.h"

/* Offsets of the fields patched in the first kerning glyph record. */
#define RECORD_OFFSET       (BINRES_FONT_HEADER_SIZE + BINRES_PAGE_HEADER_SIZE)
#define MAP_OFFSET_FIELD    (RECORD_OFFSET + 4)
#define DATA_SIZE_FIELD     (RECORD_OFFSET + 18)
#define KERNING_SIZE_FIELD  (RECORD_OFFSET + 22)

/* Where the glyph's data block starts: straight after its record. */
#define DATA_START          (RECORD_OFFSET + BINRES_KERNING_GLYPH_HEADER_SIZE)

/* Runs the load pass over the font as it now stands, with the given extent. */
static UINT patched_font_load(ULONG root_size)
{
GX_BINRES_DATA_INFO info;
GX_FONT            *font = GX_NULL;

    binres_test_root_size = root_size;
    binres_info_reset(&info);
    memset(binres_test_buffer, 0, sizeof(binres_test_buffer));
    info.gx_binres_buffer = binres_test_buffer;
    info.gx_binres_buffer_size = BINRES_TEST_BUFFER_SIZE;
    info.gx_binres_buffer_index = 0;

    return _gx_binres_one_font_load(&info, &font);
}

static VOID control_thread_entry(ULONG input)
{
int failed_tests = 0;

    /* A four-byte data block whose map offset points before it is refused; the
       same block with the map at its start loads. */
    binres_font_build(0x41, 0x41, GX_FONT_FORMAT_KERNING, 1);
    binres_put_u32(binres_test_font + DATA_SIZE_FIELD, 4);
    binres_put_u32(binres_test_font + MAP_OFFSET_FIELD, 0);
    EXPECT_EQ(GX_INVALID_FORMAT, patched_font_load(DATA_START + 4));

    binres_put_u32(binres_test_font + MAP_OFFSET_FIELD, DATA_START);
    EXPECT_EQ(GX_SUCCESS, patched_font_load(DATA_START + 4));

    /* A kerning table running past the end of the resource is refused; one
       that fits loads. */
    binres_font_build(0x41, 0x41, GX_FONT_FORMAT_KERNING, 1);
    binres_put_u16(binres_test_font + KERNING_SIZE_FIELD, 100);
    EXPECT_EQ(GX_INVALID_FORMAT, patched_font_load(DATA_START));

    binres_put_u16(binres_test_font + KERNING_SIZE_FIELD, 4);
    EXPECT_EQ(GX_SUCCESS, patched_font_load(DATA_START + 4));

    binres_test_root_size = 0;

    if (failed_tests == 0)
    {
        printf("Guix Test:   guix_binres_kerning_glyph_bounds_no_output......................................Success!\n");
        exit(0);
    }
    else
    {
        printf("Guix Test:   guix_binres_kerning_glyph_bounds_no_output.......................................Failed!\n");
        exit(1);
    }
}
